delta_asset_turnover.formula:
AT = Revenue_TTM / TotalAssets
Delta = AT_t - AT_{t-252}
Factor = CrossSectionalRank(Delta)

delta_cash_ratio.formula:
CashRatio = (Cash + TradingAssets) / CurrentLiability
Delta = CashRatio_t - CashRatio_{t-252}
Factor = CrossSectionalRank(Delta)

delta_de.formula:
DE = TotalLiability / TotalShareholderEquity
Delta = DE_t - DE_{t-252}
Factor = CrossSectionalRank(Delta)

delta_inventory_turnover.formula:
IT = Cost_TTM / Inventories
Delta = IT_t - IT_{t-252}
Factor = CrossSectionalRank(Delta)

delta_opm.formula:
OPM = OperatingProfit / OperatingRevenue
Delta = OPM_t - OPM_{t-252}
Factor = CrossSectionalRank(Delta)

eaa.formula:
1. EGA = EPS_Q / EPS_Q_{t-252} - 1
2. EAA = EGA - EGA_{t-63}
Factor = CrossSectionalRank(EAA)

eap.formula:
1. EGP = (EPS_Q_t - EPS_Q_{t-252}) / Close
2. EAP = EGP - EGP_{t-63}
Factor = CrossSectionalRank(EAP)

pa.formula:
1. PG = ROA_t - ROA_{t-252}
2. PA = PG - PG_{t-63}
Factor = CrossSectionalRank(PA)
